import { Cell } from '@ton/core';

// Copy the calculateCellsAndBits function from gas-logger.ts
function calculateCellsAndBits(root, visited = new Set()) {
    const hash = root.hash().toString('hex');
    if (visited.has(hash)) {
        return { nBits: 0, nCells: 0 };
    }
    visited.add(hash);

    let nBits = root.bits.length;
    let nCells = 1;
    for (const ref of root.refs) {
        const childRes = calculateCellsAndBits(ref, visited);
        nBits += childRes.nBits;
        nCells += childRes.nCells;
    }
    return { nBits, nCells };
}

// Helper to create Cell from hex string
function hexToCell(hexString) {
    // Remove any spaces and convert to buffer
    const cleanHex = hexString.replace(/\s/g, '');
    const buffer = Buffer.from(cleanHex, 'hex');
    return Cell.fromBoc(buffer)[0];
}

// Test data from your snapshots
const testData = {
    'WalletV3': {
        hex: 'b5ee9c720101010100710000deff0020dd2082014c97ba218201339cbab19f71b0ed44d0d31fd31f31d70bffe304e0a4f2608308d71820d31fd31fd31ff82313bbf263ed44d0d31fd31fd3ffd15132baf2a15144baf2a204f901541055f910f2a3f8009320d74a96d307d402fb00e8d101a4c8cb1fcb1fcbffc9ed54',
        recorded: { bits: 888, cells: 1 }
    },
    'WalletV4': {
        hex: '',
        recorded: { bits: 5261, cells: 20 }
    },
    'WalletV5': {
        hex: '',
        recorded: { bits: 4583, cells: 20 }
    },
    'HighloadWalletV3': {
        hex: '',
        recorded: { bits: 3997, cells: 16 }
    }
};

// Test each wallet
console.log('🔍 Verifying Bytecode Sizes\n');

for (const [name, data] of Object.entries(testData)) {
    try {
        const cell = hexToCell(data.hex);
        const { nBits, nCells } = calculateCellsAndBits(cell);

        console.log(`${name}:`);
        console.log(`  Recorded: ${data.recorded.bits} bits, ${data.recorded.cells} cells`);
        console.log(`  Calculated: ${nBits} bits, ${nCells} cells`);

        if (nBits === data.recorded.bits && nCells === data.recorded.cells) {
            console.log(`  ✅ MATCH!\n`);
        } else {
            console.log(`  ❌ MISMATCH!\n`);
        }
    } catch (error) {
        console.log(`${name}: ❌ ERROR - ${error.message}\n`);
    }
}
